const arg = argumentName ? argumentName.toLowerCase() : '';
const fs = require('fs');
const rPath = require('path');
const cfgPath = rPath.resolve(__rootdir, 'antidel.json');
const selfJid = sock.user?.id.split(':')[0] + '@s.whatsapp.net';
const defaultTarget = (botInfo.permissions.numbers[0] ? botInfo.permissions.numbers[0] + '@s.whatsapp.net' : null) || selfJid;

let cfg = { enabled: true, target: defaultTarget };
try {
  if (fs.existsSync(cfgPath)) {
    const parsed = JSON.parse(fs.readFileSync(cfgPath, 'utf8'));
    cfg.enabled = typeof parsed.enabled === 'boolean' ? parsed.enabled : cfg.enabled;
    if (typeof parsed.target === 'string' && parsed.target.includes('@')) cfg.target = parsed.target;
  }
} catch(e) {}

if (arg === 'on') {
  cfg.enabled = true;
  fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2));
  return sendTrackedMessage(sock, remoteJid, `✅ Anti-Delete *ON* — forwarding to ${cfg.target}`);
} else if (arg === 'off') {
  cfg.enabled = false;
  fs.writeFileSync(cfgPath, JSON.stringify(cfg, null, 2));
  return sendTrackedMessage(sock, remoteJid, '❌ Anti-Delete *OFF*');
}
await sendTrackedMessage(sock, remoteJid, `*Anti-Delete Status*\nEnabled: ${cfg.enabled ? 'ON ✅' : 'OFF ❌'}\nTarget: ${cfg.target}\n\nUsage: !antidel on | off`);

